125:     };
126: 
127: function compareStrings(a: string, b: string): number {
128:   if (a < b) return -1;
129:   if (a > b) return 1;
130:   return 0;
131: }
132: 
133: function isTraversalScope(value: unknown): value is LineageTraversalScope {
134:   return typeof value === 'string' && (TRAVERSAL_SCOPES as readonly string[]).includes(value);
135: }
136: 
137: function relationAllowed(scope: LineageTraversalScope, relation: LineageRelationType): boolean {
138:   if (scope === 'CONTINUATION_ONLY') {
139:     return relation === 'CONTINUATION';
140:   }
141:   if (scope === 'CONTINUATION_AND_FORK') {
142:     return relation === 'CONTINUATION' || relation === 'FORKED_FROM';
143:   }
144:   return true;
145: }
146: 
147: function edgeRef(edge: DeepReadonly<LineageEdge>): EdgeRef {
148:   return {
149:     child: edge.child,
150:     parent: edge.parent,
151:     relation: edge.relation,
152:   };
153: }
154: 
155: function frozenPath(scope: LineageTraversalScope, edges: readonly LineageEdge[]): Path {
156:   return deepFreeze({
157:     scope,
158:     edges: edges.map((edge) => ({
159:       child: edge.child,
160:       parent: edge.parent,
161:       relation: edge.relation,
162:     })),
163:   }) as Path;
164: }
165: 
166: function pathKey(path: Path): string {
167:   return path.edges
168:     .map((edge) => `${String(edge.child)}\u0000${String(edge.parent)}\u0000${edge.relation}`)
169:     .join('\u0001');
170: }
171: 
172: type GraphEdgeIndex = ReadonlyMap<IdentityVersionID, ReadonlyMap<IdentityVersionID, ReadonlySet<LineageRelationType>>>;
173: 
174: // Built once per graph instance and reused: a graph is an immutable input, so
175: // the index cannot go stale. Weak keys keep it collected with the graph.
176: const GRAPH_EDGE_INDEX: WeakMap<object, GraphEdgeIndex> = new WeakMap<object, GraphEdgeIndex>();
177: 
178: function graphEdgeIndex(graph: LineageGraph): GraphEdgeIndex {
179:   const cached = GRAPH_EDGE_INDEX.get(graph);
180:   if (cached !== undefined) {
181:     return cached;
182:   }
183:   const index = new Map<IdentityVersionID, Map<IdentityVersionID, Set<LineageRelationType>>>();
184:   for (const edge of graph.edges) {
185:     let byParent = index.get(edge.child);
186:     if (byParent === undefined) {
187:       byParent = new Map<IdentityVersionID, Set<LineageRelationType>>();
188:       index.set(edge.child, byParent);
189:     }
190:     let relations = byParent.get(edge.parent);
191:     if (relations === undefined) {
192:       relations = new Set<LineageRelationType>();
193:       byParent.set(edge.parent, relations);
194:     }
195:     relations.add(edge.relation);
196:   }
197:   GRAPH_EDGE_INDEX.set(graph, index);
198:   return index;
199: }
200: 
201: /**
202:  * A path is meaningful only against the graph it was discovered from. Every
203:  * edge must exist in that graph; without this check a path assembled from a
204:  * stale snapshot or from another domain's JSON would validate against any
205:  * graph that happens to accept its declarations.
206:  *
207:  * Membership is an O(1) lookup in the cached index, so neither a per-call key
208:  * set (one string per graph edge) nor an O(N x M) scan is needed. The index is
209:  * keyed by node identity rather than by concatenated key strings, because an id
210:  * may contain any character and would make a separator-based key ambiguous.
211:  */
212: function pathMembershipFailure(path: Path, graph: LineageGraph): Result<void> {
213:   const index = graphEdgeIndex(graph);
214:   for (const edge of path.edges) {
215:     const present = index.get(edge.child)?.get(edge.parent)?.has(edge.relation) === true;
216:     if (!present) {
217:       return pathMechanismFailure(
218:         `Path edge ${String(edge.child)} -[${edge.relation}]-> ${String(edge.parent)} is not present in the supplied graph`,
219:       );
220:     }
221:   }
222:   return { ok: true, value: undefined };
223: }
224: 
225: function noPath(candidateID: IdentityVersionID, originID: IdentityVersionID): Result<never> {
226:   return {
227:     ok: false,
228:     error: specFailure(
229:       'ERR_NO_TRAVERSAL_PATH',
230:       `No permitted path from ${candidateID} to ${originID} under the selected scope`,
231:     ),
232:   };
233: }
234: 
235: function pathMechanismFailure(message: string): Result<never> {
236:   return { ok: false, error: mechanismFailure('E_UNKNOWN_BOUNDARY_REJECTED', message) };
237: }
238: 
239: function reachableToOrigin(
240:   graph: LineageGraph,
241:   scope: LineageTraversalScope,
242:   originID: IdentityVersionID,
243: ): ReadonlySet<IdentityVersionID> {
244:   const reverse = new Map<IdentityVersionID, IdentityVersionID[]>();
245:   for (const edge of graph.edges) {
246:     if (!relationAllowed(scope, edge.relation)) {
247:       continue;
248:     }
249:     // Duplicate entries are harmless: `reachable` prevents a node from being
250:     // queued twice, and total work stays linear in the number of edges.
251:     const children = reverse.get(edge.parent) ?? [];
252:     children.push(edge.child);
253:     reverse.set(edge.parent, children);
254:   }
255: 
256:   const reachable = new Set<IdentityVersionID>([originID]);
257:   const queue: IdentityVersionID[] = [originID];
258:   // A for...of array iterator observes elements appended during iteration,
259:   // which is what this BFS relies on.
260:   for (const node of queue) {
261:     for (const child of reverse.get(node) ?? []) {
262:       if (!reachable.has(child)) {
263:         reachable.add(child);
264:         queue.push(child);
265:       }
266:     }
267:   }
268:   return reachable;
269: }
270: 
271: function adjacencyFor(
272:   graph: LineageGraph,
273:   scope: LineageTraversalScope,
274:   reachable: ReadonlySet<IdentityVersionID>,
275: ): Map<IdentityVersionID, LineageEdge[]> {
276:   const adjacency = new Map<IdentityVersionID, LineageEdge[]>();
277: 
278:   for (const edge of graph.edges) {
279:     if (!relationAllowed(scope, edge.relation) || !reachable.has(edge.parent)) {
280:       continue;
281:     }
282:     const edges = adjacency.get(edge.child) ?? [];
283:     if (!edges.some((item) => item.parent === edge.parent && item.relation === edge.relation)) {
284:       edges.push({ child: edge.child, parent: edge.parent, relation: edge.relation });
285:     }
286:     adjacency.set(edge.child, edges);
287:   }
288: 
289:   for (const edges of adjacency.values()) {
290:     edges.sort((a, b) => compareStrings(a.parent, b.parent) || compareStrings(a.relation, b.relation));
291:   }
292:   return adjacency;
293: }
294: 
295: interface DiscoveryFrame {
296:   readonly node: IdentityVersionID;
297:   readonly edges: readonly LineageEdge[];
298:   next: number;
299:   readonly visited: ReadonlySet<IdentityVersionID>;
300: }
301: 
302: type CandidatePrecheck =
303:   | { readonly ok: true }
304:   | { readonly ok: false; readonly mismatch: true }
305:   | { readonly ok: false; readonly mismatch: false; readonly error: MechanismFailure };
306: 
307: function collectPaths(
308:   adjacency: ReadonlyMap<IdentityVersionID, readonly LineageEdge[]>,
309:   scope: LineageTraversalScope,
310:   candidateID: IdentityVersionID,
311:   originID: IdentityVersionID,
312: ): Path[] {
313:   const paths: Path[] = [];
314:   const stack: DiscoveryFrame[] = [
315:     {
316:       node: candidateID,
317:       edges: [],
318:       next: 0,
319:       visited: new Set<IdentityVersionID>([candidateID]),
320:     },
321:   ];
322: 
323:   while (stack.length > 0) {
324:     const frame = stack.at(-1);
325:     if (frame === undefined) {
326:       break;
327:     }
328: 
329:     if (frame.node === originID) {
330:       if (frame.edges.length > 0) {
331:         paths.push(frozenPath(scope, frame.edges));
332:       }
333:       stack.pop();
334:       continue;
335:     }
336: 
337:     const edges = adjacency.get(frame.node) ?? [];
338:     if (frame.next >= edges.length) {
339:       stack.pop();
340:       continue;
341:     }
342: 
343:     const edge = edges[frame.next];
344:     frame.next += 1;
345:     if (frame.visited.has(edge.parent)) {
346:       continue;
347:     }
348: 
349:     const visited = new Set(frame.visited);
350:     visited.add(edge.parent);
351:     stack.push({ node: edge.parent, edges: [...frame.edges, edge], next: 0, visited });
352:   }
353: 
354:   return paths;
355: }
356: 
357: /**
358:  * Phase 1: discovers all simple candidate-to-origin paths permitted by the
359:  * selected scope. Cycle-forming and unresolved parents are dead ends.
360:  */
361: export function discoverPaths(
362:   graph: LineageGraph,
363:   scope: LineageTraversalScope,
364:   candidateID: IdentityVersionID,
365:   originID: IdentityVersionID,
366: ): Result<PathSet> {
367:   if (!isTraversalScope(scope)) {
368:     return pathMechanismFailure(`Unknown traversal scope: ${String(scope)}`);
369:   }
370:   if (candidateID === originID) {
371:     return noPath(candidateID, originID);
372:   }
373:   if (!graph.nodes.includes(candidateID) || !graph.nodes.includes(originID)) {
374:     return noPath(candidateID, originID);
375:   }
376: 
377:   const reachable = reachableToOrigin(graph, scope, originID);
378:   if (!reachable.has(candidateID)) {
379:     return noPath(candidateID, originID);
380:   }
381: 
382:   const paths = collectPaths(adjacencyFor(graph, scope, reachable), scope, candidateID, originID);
383:   if (paths.length === 0) {
384:     return noPath(candidateID, originID);
385:   }
386: 
387:   paths.sort((a, b) => compareStrings(pathKey(a), pathKey(b)));
388:   return { ok: true, value: Object.freeze(paths) };
389: }
390: 
391: function validatePathShape(path: Path): Result<void> {
392:   if (!isTraversalScope(path.scope)) {
393:     return pathMechanismFailure(`Unknown traversal scope: ${String(path.scope)}`);
394:   }
395:   if (path.edges.length === 0) {
396:     return pathMechanismFailure('Path must contain at least one edge');
397:   }
398: 
399:   const seen = new Set<IdentityVersionID>([path.edges[0].child]);
400:   for (let index = 0; index < path.edges.length; index += 1) {
401:     const edge = path.edges[index];
402:     if (!relationAllowed(path.scope, edge.relation)) {
403:       return pathMechanismFailure('Path edge violates the traversal scope');
404:     }
405:     if (index > 0 && path.edges[index - 1].parent !== edge.child) {
406:       return pathMechanismFailure('Path edges are not contiguous in candidate-to-origin order');
407:     }
408:     if (seen.has(edge.parent)) {
409:       return pathMechanismFailure('Path contains a cycle');
410:     }
411:     seen.add(edge.parent);
412:   }
413: 
414:   return { ok: true, value: undefined };
415: }
416: 
417: function validationValue(value: PathValidation): Result<PathValidation> {
418:   return { ok: true, value: deepFreeze(value) as PathValidation };
419: }
420: 
421: type CycleIndex = ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>;
422: 
423: function buildCycleIndex(graph: LineageGraph): CycleIndex {
424:   const index = new Map<IdentityVersionID, readonly IdentityVersionID[]>();
425:   for (const cycle of graph.cycles) {
426:     for (const node of cycle) {
427:       index.set(node, cycle);
428:     }
429:   }
430:   return index;
431: }
432: 
433: type EdgeAssuranceOutcome =
434:   | { readonly status: 'SATISFIED' }
435:   | { readonly status: 'NO_APPLICABLE_ASSESSMENT' }
436:   | {
437:       readonly status: 'UNSATISFIED';
438:       readonly missing: readonly string[];
439:       readonly disallowed: readonly string[];
440:     }
441:   | { readonly status: 'CONTESTED'; readonly contestedClaims: readonly string[] };
442: 
443: /** Shared Phase 2/3 edge evaluation; Task 8 owns applicability and assurance. */
444: function evaluateEdgeAssurance(
445:   branch: EdgeRef,
446:   assessments: readonly ContinuityAssessment[],
447:   requirement: ContinuityAssuranceRequirement,
448:   policy: Policy,
449:   ctx: TemporalContext,
450: ): Result<EdgeAssuranceOutcome> {
451:   const applicable = assessEdge(branch, assessments, policy, ctx);
452:   if (!applicable.ok) {
453:     return applicable;
454:   }
455:   if (applicable.value.unresolved) {
456:     return { ok: true, value: { status: 'NO_APPLICABLE_ASSESSMENT' } };
457:   }
458: 
459:   const assurance = evaluateAssurance(applicable.value, requirement, policy, ctx);
460:   if (assurance.status === 'MECHANISM') {
461:     // Drop the assurance-only `status` discriminant, but keep every Failure
462:     // field, including `details` if a mechanism result ever carries one.
463:     const failure: MechanismFailure = {
464:       kind: assurance.kind,
465:       code: assurance.code,
466:       message: assurance.message,
467:       ...(assurance.details === undefined ? {} : { details: assurance.details }),
468:     };
469:     return { ok: false, error: failure };
470:   }
471:   if (assurance.status === 'SATISFIED') {
472:     return { ok: true, value: { status: 'SATISFIED' } };
473:   }
474:   if (assurance.status === 'UNSATISFIED') {
475:     return {
476:       ok: true,
477:       value: {
478:         status: 'UNSATISFIED',
479:         missing: assurance.missing,
480:         disallowed: assurance.disallowed,
481:       },
482:     };
483:   }
484:   return {
485:     ok: true,
486:     value: { status: 'CONTESTED', contestedClaims: assurance.contestedClaims },
487:   };
488: }
489: 
490: function cycleForPath(path: Path, index: CycleIndex): readonly IdentityVersionID[] | undefined {
491:   const cycles = new Set<readonly IdentityVersionID[]>();
492:   for (const edge of path.edges) {
493:     const childCycle = index.get(edge.child);
494:     if (childCycle !== undefined) {
495:       cycles.add(childCycle);
496:     }
497:     const parentCycle = index.get(edge.parent);
498:     if (parentCycle !== undefined) {
499:       cycles.add(parentCycle);
500:     }
501:   }
502: 
503:   if (cycles.size === 0) {
504:     return undefined;
505:   }
506: 
507:   const combined = new Set<IdentityVersionID>();
508:   for (const cycle of cycles) {
509:     for (const node of cycle) {
510:       combined.add(node);
511:     }
512:   }
513:   return [...combined].sort(compareStrings);
514: }
515: 
516: /**
517:  * Phase 2: validates one concrete path edge by edge. Task 8 owns assessment
518:  * applicability and assurance; this function only sequences the calls and
519:  * preserves the first failing edge.
520:  */
521: export function validatePath(
522:   path: Path,
523:   graph: LineageGraph,
524:   assessments: readonly ContinuityAssessment[],
525:   requirement: ContinuityAssuranceRequirement,
526:   policy: Policy,
527:   ctx: TemporalContext,
528: ): Result<PathValidation> {
529:   const shape = validatePathShape(path);
530:   if (!shape.ok) {
531:     return shape;
532:   }
533:   const membership = pathMembershipFailure(path, graph);
534:   if (!membership.ok) {
535:     return membership;
536:   }
537:   return validatePathWithIndex(path, buildCycleIndex(graph), assessments, requirement, policy, ctx);
538: }
539: 
540: function validatePathWithIndex(
541:   path: Path,
542:   cycleIndex: CycleIndex,
543:   assessments: readonly ContinuityAssessment[],
544:   requirement: ContinuityAssuranceRequirement,
545:   policy: Policy,
546:   ctx: TemporalContext,
547: ): Result<PathValidation> {
548:   const shape = validatePathShape(path);
549:   if (!shape.ok) {
550:     return shape;
551:   }
552: 
553:   const cycle = cycleForPath(path, cycleIndex);
554:   if (cycle !== undefined) {
555:     return validationValue({ status: 'CYCLE_DETECTED', code: 'CYCLE_DETECTED', cycle });
556:   }
557: 
558:   for (const edge of path.edges) {
559:     const reference = edgeRef(edge);
560:     const outcome = evaluateEdgeAssurance(reference, assessments, requirement, policy, ctx);
561:     if (!outcome.ok) {
562:       return outcome;
563:     }
564: 
565:     if (outcome.value.status === 'SATISFIED') {
566:       continue;
567:     }
568:     if (outcome.value.status === 'NO_APPLICABLE_ASSESSMENT') {
569:       return validationValue({
570:         status: 'INVALID',
571:         code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
572:         edge: reference,
573:         missing: [...requirement.required_claims].sort(compareStrings),
574:         disallowed: [],
575:       });
576:     }
577:     if (outcome.value.status === 'UNSATISFIED') {
578:       return validationValue({
579:         status: 'INVALID',
580:         code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
581:         edge: reference,
582:         missing: outcome.value.missing,
583:         disallowed: outcome.value.disallowed,
584:       });
585:     }
586:     return validationValue({
587:       status: 'CONTESTED',
588:       edge: reference,
589:       contestedClaims: outcome.value.contestedClaims,
590:     });
591:   }
592: 
593:   return validationValue({ status: 'VALID' });
594: }
595: 
596: function directParentBranches(graph: LineageGraph, child: IdentityVersionID): EdgeRef[] {
597:   const branches = new Map<string, EdgeRef>();
598:   for (const candidate of graph.edges) {
599:     if (candidate.child !== child) {
600:       continue;
601:     }
602:     const branch = edgeRef(candidate);
603:     branches.set(`${String(branch.parent)}\u0000${branch.relation}`, branch);
604:   }
605:   return [...branches.values()].sort(
606:     (a, b) => compareStrings(a.parent, b.parent) || compareStrings(a.relation, b.relation),
607:   );
608: }
609: 
610: function evaluateClosureBranch(
611:   branch: EdgeRef,
612:   assessments: readonly ContinuityAssessment[],
613:   requirement: ContinuityAssuranceRequirement,
614:   policy: Policy,
615:   ctx: TemporalContext,
616: ): Result<MergeClosureBranchFailure | undefined> {
617:   const outcome = evaluateEdgeAssurance(branch, assessments, requirement, policy, ctx);
618:   if (!outcome.ok) {
619:     return outcome;
620:   }
621: 
622:   if (outcome.value.status === 'SATISFIED') {
623:     return { ok: true, value: undefined };
624:   }
625:   if (outcome.value.status === 'NO_APPLICABLE_ASSESSMENT') {
626:     return { ok: true, value: { branch, reason: 'NO_APPLICABLE_ASSESSMENT' } };
627:   }
628:   if (outcome.value.status === 'UNSATISFIED') {
629:     return {
630:       ok: true,
631:       value: {
632:         branch,
633:         reason: 'ASSURANCE_UNSATISFIED',
634:         missing: outcome.value.missing,
635:         disallowed: outcome.value.disallowed,
636:       },
637:     };
638:   }
639:   return {
640:     ok: true,
641:     value: { branch, reason: 'CONTESTED', contestedClaims: outcome.value.contestedClaims },
642:   };
643: }
644: 
645: function closureBranchKey(branch: EdgeRef): string {
646:   return `${String(branch.child)}\u0000${String(branch.parent)}\u0000${branch.relation}`;
647: }
648: 
649: function collectBranchFailure(
650:   failures: Map<string, MergeClosureBranchFailure>,
651:   edge: EdgeRef,
652:   branch: EdgeRef,
653:   assessments: readonly ContinuityAssessment[],
654:   requirement: ContinuityAssuranceRequirement,
655:   policy: Policy,
656:   ctx: TemporalContext,
657: ): Result<undefined> {
658:   if (branch.parent === edge.parent && branch.relation === edge.relation) {
659:     return { ok: true, value: undefined };
660:   }
661:   const key = closureBranchKey(branch);
662:   if (failures.has(key)) {
663:     return { ok: true, value: undefined };
664:   }
665: 
666:   const failure = evaluateClosureBranch(branch, assessments, requirement, policy, ctx);
667:   if (!failure.ok) {
668:     return failure;
669:   }
670:   if (failure.value !== undefined) {
671:     failures.set(key, failure.value);
672:   }
673:   return { ok: true, value: undefined };
674: }
675: 
676: function collectEdgeClosureFailures(
677:   failures: Map<string, MergeClosureBranchFailure>,
678:   edge: EdgeRef,
679:   graph: LineageGraph,
680:   assessments: readonly ContinuityAssessment[],
681:   requirement: ContinuityAssuranceRequirement,
682:   policy: Policy,
683:   ctx: TemporalContext,
684: ): Result<undefined> {
685:   const branches = directParentBranches(graph, edge.child);
686:   if (!branches.some((branch) => branch.relation === 'MERGED_FROM')) {
687:     return { ok: true, value: undefined };
688:   }
689: 
690:   for (const branch of branches) {
691:     const collected = collectBranchFailure(failures, edge, branch, assessments, requirement, policy, ctx);
692:     if (!collected.ok) {
693:       return collected;
694:     }
695:   }
696:   return { ok: true, value: undefined };
697: }
698: 
699: function collectClosureFailures(
700:   path: Path,
701:   graph: LineageGraph,
702:   assessments: readonly ContinuityAssessment[],
703:   requirement: ContinuityAssuranceRequirement,
704:   policy: Policy,
705:   ctx: TemporalContext,
706: ): Result<Map<string, MergeClosureBranchFailure>> {
707:   const failures = new Map<string, MergeClosureBranchFailure>();
708: 
709:   for (const edge of path.edges) {
710:     const collected = collectEdgeClosureFailures(failures, edge, graph, assessments, requirement, policy, ctx);
711:     if (!collected.ok) {
712:       return collected;
713:     }
714:   }
715: 
716:   return { ok: true, value: failures };
717: }
718: 
719: function closureResult(failures: ReadonlyMap<string, MergeClosureBranchFailure>): MergeClosureResult {
720:   if (failures.size === 0) {
721:     return deepFreeze({ status: 'SATISFIED' }) as MergeClosureResult;
722:   }
723: 
724:   const orderedFailures = [...failures.values()].sort(
725:     (a, b) =>
726:       compareStrings(a.branch.child, b.branch.child) ||
727:       compareStrings(a.branch.parent, b.branch.parent) ||
728:       compareStrings(a.branch.relation, b.branch.relation),
729:   );
730:   return deepFreeze({
731:     status: 'UNSATISFIED',
732:     code: 'ERR_MERGE_BRANCH_UNSATISFIED',
733:     failures: orderedFailures,
734:   }) as MergeClosureResult;
735: }
736: 
737: /**
738:  * Phase 3: immediate merge closure. For every MERGED_FROM node on the path,
739:  * every direct parent edge of that node is checked, whatever its relation.
740:  * The exact edge already validated by Phase 2 is skipped; closure-only
741:  * branches are not recursed.
742:  */
743: export function validateMergeClosure(
744:   path: Path,
745:   graph: LineageGraph,
746:   assessments: readonly ContinuityAssessment[],
747:   requirement: ContinuityAssuranceRequirement,
748:   policy: Policy,
749:   ctx: TemporalContext,
750: ): Result<MergeClosureResult> {
751:   const shape = validatePathShape(path);
752:   if (!shape.ok) {
753:     return shape;
754:   }
755:   const membership = pathMembershipFailure(path, graph);
756:   if (!membership.ok) {
757:     return membership;
758:   }
759:   return validateMergeClosureAgainstGraph(path, graph, assessments, requirement, policy, ctx);
760: }
761: 
762: /** Closure over an already-checked path (evaluateBinding passes discovered paths). */
763: function validateMergeClosureAgainstGraph(
764:   path: Path,
765:   graph: LineageGraph,
766:   assessments: readonly ContinuityAssessment[],
767:   requirement: ContinuityAssuranceRequirement,
768:   policy: Policy,
769:   ctx: TemporalContext,
770: ): Result<MergeClosureResult> {
771:   const collected = collectClosureFailures(path, graph, assessments, requirement, policy, ctx);
772:   if (!collected.ok) {
773:     return collected;
774:   }
775:   return { ok: true, value: closureResult(collected.value) };
