60: /**
61:  * Effective count per relation. MERGED_FROM joins distinct parent lines, so
62:  * duplicate links to one parent count once (§5.2).
63:  */
64: function relationCounts(lineage: readonly DeepReadonly<LineageLink>[]): Readonly<Record<LineageRelationType, number>> {
65:   const counts: Record<LineageRelationType, number> = {
66:     CONTINUATION: 0,
67:     FORKED_FROM: 0,
68:     MERGED_FROM: 0,
69:   };
70:   const mergedParents = new Set<IdentityVersionID>();
71: 
72:   for (const link of lineage) {
73:     if (link.relation === 'MERGED_FROM') {
74:       mergedParents.add(link.parent_version_id);
75:     } else {
76:       counts[link.relation] += 1;
77:     }
78:   }
79:   counts.MERGED_FROM = mergedParents.size;
80:   return counts;
