186: function collectUnresolvedParents(
187:   nodes: ReadonlySet<IdentityVersionID>,
188:   edges: readonly LineageEdge[],
189: ): LineageGraph['unresolvedParents'] {
190:   const missingByChild = new Map<IdentityVersionID, Set<IdentityVersionID>>();
