229: function finishOrder(
230:   nodes: readonly IdentityVersionID[],
231:   adjacency: ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>,
232: ): IdentityVersionID[] {
233:   const visited = new Set<IdentityVersionID>();
234:   const order: IdentityVersionID[] = [];
235: 
236:   for (const start of nodes) {
237:     if (visited.has(start)) {
238:       continue;
239:     }
240:     visited.add(start);
241:     const stack: Array<{ node: IdentityVersionID; next: number }> = [{ node: start, next: 0 }];
242: 
243:     while (stack.length > 0) {
244:       const frame = stack.at(-1);
245:       if (frame === undefined) {
246:         break;
247:       }
248:       const parents = adjacency.get(frame.node) ?? [];
249: 
250:       if (frame.next >= parents.length) {
251:         order.push(frame.node);
252:         stack.pop();
253:         continue;
254:       }
255: 
256:       const parent = parents[frame.next];
257:       frame.next += 1;
258:       if (!visited.has(parent) && adjacency.has(parent)) {
259:         visited.add(parent);
260:         stack.push({ node: parent, next: 0 });
261:       }
262:     }
263:   }
264: 
265:   return order;
266: }
