268: function reverseAdjacency(
269:   nodes: readonly IdentityVersionID[],
270:   adjacency: ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>,
271: ): Map<IdentityVersionID, IdentityVersionID[]> {
272:   const reverse = new Map<IdentityVersionID, IdentityVersionID[]>();
273:   for (const node of nodes) {
274:     reverse.set(node, []);
275:   }
276:   for (const [child, parents] of adjacency) {
277:     for (const parent of parents) {
278:       reverse.get(parent)?.push(child);
279:     }
280:   }
281:   for (const children of reverse.values()) {
282:     children.sort(compareStrings);
283:   }
284:   return reverse;
285: }
