287: function stronglyConnectedComponents(
288:   nodes: readonly IdentityVersionID[],
289:   adjacency: ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>,
290: ): IdentityVersionID[][] {
291:   const order = finishOrder(nodes, adjacency);
292:   const reverse = reverseAdjacency(nodes, adjacency);
293:   const assigned = new Set<IdentityVersionID>();
294:   const components: IdentityVersionID[][] = [];
295: 
296:   for (let index = order.length - 1; index >= 0; index -= 1) {
297:     const start = order[index];
298:     if (assigned.has(start)) {
299:       continue;
300:     }
301: 
302:     const component: IdentityVersionID[] = [];
303:     const stack: IdentityVersionID[] = [start];
304:     assigned.add(start);
305: 
306:     while (stack.length > 0) {
307:       const node = stack.pop();
308:       if (node === undefined) {
309:         break;
310:       }
311:       component.push(node);
312:       for (const child of reverse.get(node) ?? []) {
313:         if (!assigned.has(child)) {
314:           assigned.add(child);
315:           stack.push(child);
316:         }
317:       }
318:     }
319: 
320:     component.sort(compareStrings);
321:     components.push(component);
322:   }
323: 
324:   components.sort((a, b) => compareStrings(a[0], b[0]));
325:   return components;
326: }
