import { describe, expect, test } from 'bun:test';
import * as fc from 'fast-check';
import { buildCase, dagSpecArbitrary } from '../property/support/dag-fixtures.js';
import * as current from '../../src/core/traversal.js';
import * as legacy from '../../src/core/traversal.legacy.js';

describe('differential: traversal discovery', () => {
  test('matches legacy implementation on generated DAGs', () => {
    fc.assert(
      fc.property(dagSpecArbitrary, (spec) => {
        const generated = buildCase(spec);
        const left = legacy.discoverPaths(
          generated.graph,
          generated.binding.traversal_scope,
          generated.candidate,
          generated.origin,
        );
        const right = current.discoverPaths(
          generated.graph,
          generated.binding.traversal_scope,
          generated.candidate,
          generated.origin,
        );
        expect(JSON.stringify(right)).toBe(JSON.stringify(left));
      }),
      { numRuns: 300, seed: 24_001 },
    );
  }, 60_000);

  test('is deterministic across repeated runs', () => {
    fc.assert(
      fc.property(dagSpecArbitrary, (spec) => {
        const generated = buildCase(spec);
        const first = current.discoverPaths(
          generated.graph,
          generated.binding.traversal_scope,
          generated.candidate,
          generated.origin,
        );
        const second = current.discoverPaths(
          generated.graph,
          generated.binding.traversal_scope,
          generated.candidate,
          generated.origin,
        );
        expect(JSON.stringify(second)).toBe(JSON.stringify(first));
      }),
      { numRuns: 100, seed: 24_002 },
    );
  }, 30_000);
});

import { describe, expect, test } from 'bun:test';
import { buildLineageGraph } from '../../src/core/lineage.js';
import { descriptor, link, participant, registry } from '../support/fixtures.js';
import { identityVersionId } from '../../src/core/primitives.js';
import * as current from '../../src/core/traversal.js';
import * as legacy from '../../src/core/traversal.legacy.js';

function run(graph: any, scope: any, candidate: string, origin: string) {
  const a = legacy.discoverPaths(graph, scope, identityVersionId(candidate), identityVersionId(origin));
  const b = current.discoverPaths(graph, scope, identityVersionId(candidate), identityVersionId(origin));
  expect(JSON.stringify(b)).toBe(JSON.stringify(a));
  return b;
}

describe('differential cyclic', () => {
  test('cycle without permitted path', () => {
    const alice = participant('participant-a');
    const v1 = descriptor({ id: 'iv-v1', participant: 'participant-a', lineage: [link('iv-v2', 'CONTINUATION')] });
    const v2 = descriptor({ id: 'iv-v2', participant: 'participant-a', lineage: [link('iv-v1', 'CONTINUATION')] });
    const v3 = descriptor({ id: 'iv-v3', participant: 'participant-a' });
    const graph = buildLineageGraph(registry([alice], [v1, v2, v3]));
    const result = run(graph, 'CONTINUATION_ONLY', 'iv-v1', 'iv-v3');
    expect(result.ok).toBe(false);
  });

  test('cycle in one branch plus valid branch', () => {
    const a = participant('participant-a');
    const b = participant('participant-b');
    const origin = descriptor({ id: 'iv-a-1', participant: 'participant-a' });
    const x = descriptor({ id: 'iv-x', participant: 'participant-b', lineage: [link('iv-y', 'CONTINUATION')] });
    const y = descriptor({ id: 'iv-y', participant: 'participant-b', lineage: [link('iv-x', 'CONTINUATION'), link('iv-a-1', 'CONTINUATION')] });
    const good = descriptor({ id: 'iv-good', participant: 'participant-a', lineage: [link('iv-a-1', 'CONTINUATION')] });
    const candidate = descriptor({ id: 'iv-d', participant: 'participant-d', lineage: [link('iv-x', 'MERGED_FROM'), link('iv-good', 'MERGED_FROM')] });
    const dave = participant('participant-d');
    const graph = buildLineageGraph(registry([a, b, dave], [origin, x, y, good, candidate]));
    const result = run(graph, 'FULL_ANCESTRY', 'iv-d', 'iv-a-1');
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.value.length).toBe(2);
  });

  test('repeated node in different branches is not a cycle of current path', () => {
    // diamond: d -> b,c ; b,c -> a. Node a reachable via both branches; no cycle.
    const alice = participant('participant-a');
    const bob = participant('participant-b');
    const dave = participant('participant-d');
    const a = descriptor({ id: 'iv-a-1', participant: 'participant-a', versionLabel: '1.0.0' });
    const b = descriptor({ id: 'iv-b', participant: 'participant-b', versionLabel: '1.0.0', lineage: [link('iv-a-1', 'FORKED_FROM')] });
    const c = descriptor({ id: 'iv-c', participant: 'participant-a', versionLabel: '1.0.0', lineage: [link('iv-a-1', 'CONTINUATION')] });
    const d = descriptor({ id: 'iv-d', participant: 'participant-d', versionLabel: '2.0.0', lineage: [link('iv-b', 'MERGED_FROM'), link('iv-c', 'MERGED_FROM')] });
    const graph = buildLineageGraph(registry([alice, bob, dave], [a, b, c, d]));
    const result = run(graph, 'FULL_ANCESTRY', 'iv-d', 'iv-a-1');
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.value.length).toBe(2);
  });

  test('duplicate declared edges first-wins', () => {
    const alice = participant('participant-a');
    const origin = descriptor({ id: 'iv-a-1', participant: 'participant-a', versionLabel: '1.0.0' });
    const candidate = descriptor({
      id: 'iv-a-2',
      participant: 'participant-a',
      versionLabel: '1.1.0',
      lineage: [link('iv-a-1', 'CONTINUATION'), link('iv-a-1', 'CONTINUATION')],
    });
    const graph = buildLineageGraph(registry([alice], [origin, candidate]));
    const result = run(graph, 'CONTINUATION_ONLY', 'iv-a-2', 'iv-a-1');
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value.length).toBe(1);
      expect(result.value[0].edges.length).toBe(1);
    }
  });

  test('NUL and separator IDs do not collide', () => {
    const alice = participant('participant-a');
    const parentA = 'iv\u0000a';
    const parentB = 'iv\u0001a';
    const origin = descriptor({ id: 'iv-origin', participant: 'participant-a', versionLabel: '1.0.0' });
    // two distinct parents whose string keys could collide under naive separators
    const p1 = descriptor({ id: parentA, participant: 'participant-a', versionLabel: '1.0.0', lineage: [link('iv-origin', 'CONTINUATION')] });
    const p2 = descriptor({ id: parentB, participant: 'participant-a', versionLabel: '1.0.0', lineage: [link('iv-origin', 'CONTINUATION')] });
    const candidate = descriptor({
      id: 'iv-cand',
      participant: 'participant-a',
      versionLabel: '1.0.0',
      lineage: [link(parentA, 'MERGED_FROM'), link(parentB, 'MERGED_FROM')],
    });
    const graph = buildLineageGraph(registry([alice], [origin, p1, p2, candidate]));
    const result = run(graph, 'FULL_ANCESTRY', 'iv-cand', 'iv-origin');
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.value.length).toBe(2);
  });
});

